echo 'ACTION=="add|change", KERNEL=="nvme*", ATTR{queue/scheduler}="none"' | sudo tee /etc/udev/rules.d/60-ioschedulers.rules && sudo systemctl enable --now fstrim.timer && sudo tune2fs -o journal_data_ordered -m 1 /dev/nvme0n1p && sudo sed -i -E 's/([[:space:]]\/[[:space:]]+ext4[[:space:]]+)defaults([^[:space:]]*)/\1noatime,commit=60,\2/; s/noatime,commit=60,defaults/noatime,commit=60/' /etc/fstab
